query Disponibilidad($inicio: String!, $fin: String!) {
  vehiculosDisponibles(inicio: $inicio, fin: $fin) {
    idVehiculo
    patente
    marca
    modelo
    tipoVehiculo
    precioDiario
    estado
  }
}

query DisponibilidadFiltrada($inicio: String!, $fin: String!, $filtro: FiltroDisponibilidad) {
  vehiculosDisponibles(inicio: $inicio, fin: $fin, filtro: $filtro) {
    patente
    marca
    modelo
    tipoVehiculo
    precioDiario
  }
}

query HistorialCliente($idCliente: ID!) {
  historialAlquileres(idCliente: $idCliente) {
    vehiculo
    patente
    fechaInicio
    fechaFinalizacion
    cantidadDias
    importeTotal
    estado
  }
}

query {
  reservas {
    idReserva
    cliente {
      idCliente
      nombre
      apellido
      email
    }
    vehiculo {
      idVehiculo
      patente
      marca
      modelo
    }
    fechaInicio
    fechaFin
    importeTotal
    estado
    resultadoMantenimiento
  }
}

query ReservasFiltradas($filtro: FiltroReserva) {
  reservas(filtro: $filtro) {
    idReserva
    estado
    resultadoMantenimiento
    cliente {
      nombre
      apellido
    }
    vehiculo {
      marca
      modelo
      patente
    }
    importeTotal
  }
}
